import { migrate } from "drizzle-orm/node-postgres/migrator";
import { fileURLToPath } from "node:url";
import { createDb } from "./client.js";

/** Applies SQL migrations from ./drizzle (generated by `npm run db:generate`). */
export async function runMigrations(url: string) {
  const { db, pool } = createDb(url, 1);
  const folder = fileURLToPath(new URL("../../drizzle", import.meta.url));
  try { await migrate(db, { migrationsFolder: folder }); } finally { await pool.end(); }
}
if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  runMigrations(process.env.DATABASE_URL!).then(() => console.log("migrations applied"), (e) => { console.error(e); process.exit(1); });
}
